def verify_one(args):
    idx, (va, sz, asm), tmpdir = args
    s_file = os.path.join(tmpdir, f"fn_{idx}.s")
    o_file = os.path.join(tmpdir, f"fn_{idx}.o")
    bin_file = os.path.join(tmpdir, f"fn_{idx}.bin")

    with open(s_file, "w") as f:
        f.write(asm)

    subprocess.run(["i686-w64-mingw32-as", s_file, "-o", o_file], check=True)
    subprocess.run(["objcopy", "-O", "binary", "-j", ".text", o_file, bin_file], check=True)

    with open(bin_file, "rb") as f:
        cand_bytes = f.read()[:sz]

    ok = vf.verify_function(va, candidate_bytes=cand_bytes, quiet=True)
    return idx, va, ok

def run_tests():
    print("=" * 70)
    print("RUNNING MATCHED FUNCTIONS VERIFICATION SUITE")
    print("=" * 70)

    passed = 0
    total = len(MATCHED_FUNCTIONS)
    workers = min(32, os.cpu_count() or 4)

    with tempfile.TemporaryDirectory() as tmpdir:
        tasks = [(idx, item, tmpdir) for idx, item in enumerate(MATCHED_FUNCTIONS, 1)]
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
            for idx, va, ok in executor.map(verify_one, tasks):
                if ok:
                    passed += 1
                    if idx % 100 == 0 or idx == total:
                        print(f"[{idx}/{total}] Verified: {va} (100% bit-perfect)")
                else:
                    print(f"FAILED: {va}")

    print("\n" + "=" * 70)
    print(f"VERIFICATION SUMMARY: {passed}/{total} functions 100% BIT-PERFECT MATCH")
    print("=" * 70)
    assert passed == total, f"Only {passed}/{total} functions passed!"
    return passed == total

if __name__ == "__main__":
    success = run_tests()
    sys.exit(0 if success else 1)
